_drop_d1_block() {
  local binding="$1" file="$2" tmp
  tmp=$(mktemp)
  awk -v want="$binding" '
    BEGIN { inblk = 0; skip = 0; buf = "" }
    # start of a d1 block: buffer it, decide later whether to emit
    $0 ~ /^[[:space:]]*\[\[d1_databases\]\][[:space:]]*$/ {
      inblk = 1; skip = 0; buf = $0 ORS; next
    }
    inblk == 1 {
      if ($0 ~ /^[[:space:]]*\[/) {          # next section header: block ended
        inblk = 0
        if (!skip) printf "%s", buf
        buf = ""
      } else {
        if ($0 ~ "^[[:space:]]*binding[[:space:]]*=[[:space:]]*\"" want "\"[[:space:]]*$") skip = 1
        buf = buf $0 ORS
        next
      }
    }
    { print }
    END { if (inblk && !skip) printf "%s", buf }
  ' "$file" > "$tmp"
  mv "$tmp" "$file"
}

