_drop_d1_block() {
  local binding="$1" file="$2" tmp
  tmp=$(mktemp)
  awk -v binding_re="^[[:space:]]*binding[[:space:]]*=[[:space:]]*\"${binding}\"[[:space:]]*$" '
    BEGIN { inblk = 0; skip = 0; buf = "" }

    # Start of a d1 block. Flush any previous block first, or a back-to-back
    # pair of blocks would lose the first one.
    /^[[:space:]]*\[\[d1_databases\]\][[:space:]]*$/ {
      if (inblk && !skip) printf "%s", buf
      inblk = 1; skip = 0; buf = $0 ORS; next
    }

    inblk == 1 {
      if ($0 ~ /^[[:space:]]*\[/) {     # any section header ends the block
        inblk = 0
        if (!skip) printf "%s", buf
        buf = ""
        print
        next
      }
      if ($0 ~ binding_re) skip = 1     # this is the block we came to delete
      buf = buf $0 ORS
      next
    }

    { print }

    END { if (inblk && !skip) printf "%s", buf }
  ' "$file" > "$tmp"
  mv "$tmp" "$file"
}

